select n.nspname||'.'||c.relname as tabla, t.tgname, pn.nspname||'.'||p.proname as fn, t.tgenabled from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace pn on pn.oid=p.pronamespace where not t.tgisinternal and n.nspname in ('crm','private','public') order by 1,2
